INSERT INTO traffic_signs (code, name, sign_group, meaning, standard_version, legal_status, raster_asset, search_text) VALUES
('P.101', 'Đường cấm', 'CAM', 'a) Để báo đường cấm các loại phương tiện đi lại cả hai hướng, trừ các xe được ưu tiên theo quy định, đặt biển số P.101 “Đường cấm”. b) Nếu đường cấm vì lý do đường, cầu bị tắc thì biển cấm đặt ở giữa phần xe chạy kèm theo có hàng rào chắn ngang trước phần xe chạy như quy định ở Điều 77, các xe được ưu tiên cũng không được phép đi vào. c) Nếu đường cấm cả người đi bộ, đặt thêm biển số P.112 “Cấm người đi bộ” (ở trong khu đông dân cư) hoặc kéo dài hàng rào chắn ngang suốt cả nền đường (ở ngoài khu đông dân cư). d) Nếu đường cấm vì những lý do khác nhưng cầu, đường vẫn sử dụng được thì biển đặt ở giữa đường nhưng không đặt hàng rào chắn. e) Nếu phần xe chạy quá hẹp, biển đặt ở giữa phần xe chạy sẽ làm cản trở những xe được phép ra vào đường cấm thì đặt biển ở mép phần xe chạy.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-1.png', 'p.101 duong cam'),
('P.102', 'Cấm đi ngược chiều', 'CAM', 'a) Để báo đường cấm các loại xe (cơ giới và thô sơ) đi vào theo chiều đặt biển, trừ các xe được ưu tiên theo quy định, đặt biển số P.102 “Cấm đi ngược chiều”. Người đi bộ được phép đi trên vỉa hè hoặc lề đường. b) Chiều đi ngược lại với chiều đặt biển P.102 là lối đi thuận chiều, các loại xe được phép đi do đó phải đặt biển chỉ dẫn số I.407a hoặc đặt biển số R.302 a, hoặc R.302 b ở đầu dải phân cách.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-2.png', 'p.102 cam di nguoc chieu'),
('P.103a', 'Cấm xe ôtô', 'CAM', 'a) Để báo đường cấm các loại xe cơ giới kể cả xe máy 3 bánh có thùng đi qua, trừ xe máy 2 bánh, xe gắn máy và các xe được ưu tiên theo quy định, đặt biển số P.103a “Cấm xe ôtô” Nếu đường cấm vì lý do đường, cầu bị yếu, có thể đặt hàng rào chắn hay chướng ngại vật trong phần đường xe chạy. b) Để báo đường cấm các loại xe cơ giới kể cả xe máy 3 bánh có thùng rẽ phải hay rẽ trái, trừ xe máy 2 bánh, xe gắn máy và các xe được ưu tiên theo quy định, đặt biển số P.103b “Cấm xe ô tô rẽ phải” hay biển số P.103c “Cấm xe ô tô rẽ trái”.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-3.png', 'p.103a cam xe oto'),
('P.103b', 'Cấm xe ôtô rẽ phải', 'CAM', 'a) Để báo đường cấm các loại xe cơ giới kể cả xe máy 3 bánh có thùng đi qua, trừ xe máy 2 bánh, xe gắn máy và các xe được ưu tiên theo quy định, đặt biển số P.103a “Cấm xe ôtô” Nếu đường cấm vì lý do đường, cầu bị yếu, có thể đặt hàng rào chắn hay chướng ngại vật trong phần đường xe chạy. b) Để báo đường cấm các loại xe cơ giới kể cả xe máy 3 bánh có thùng rẽ phải hay rẽ trái, trừ xe máy 2 bánh, xe gắn máy và các xe được ưu tiên theo quy định, đặt biển số P.103b “Cấm xe ô tô rẽ phải” hay biển số P.103c “Cấm xe ô tô rẽ trái”.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-3.png', 'p.103b cam xe oto re phai'),
('P.103c', 'Cấm xe ôtô rẽ trái', 'CAM', 'a) Để báo đường cấm các loại xe cơ giới kể cả xe máy 3 bánh có thùng đi qua, trừ xe máy 2 bánh, xe gắn máy và các xe được ưu tiên theo quy định, đặt biển số P.103a “Cấm xe ôtô” Nếu đường cấm vì lý do đường, cầu bị yếu, có thể đặt hàng rào chắn hay chướng ngại vật trong phần đường xe chạy. b) Để báo đường cấm các loại xe cơ giới kể cả xe máy 3 bánh có thùng rẽ phải hay rẽ trái, trừ xe máy 2 bánh, xe gắn máy và các xe được ưu tiên theo quy định, đặt biển số P.103b “Cấm xe ô tô rẽ phải” hay biển số P.103c “Cấm xe ô tô rẽ trái”.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-3.png', 'p.103c cam xe oto re trai'),
('P.104', 'Cấm xe máy', 'CAM', 'Để báo đường cấm các loại xe máy, trừ các xe được ưu tiên theo quy định, đặt biển số P.104 “Cấm xe máy”. Biển không có giá trị cấm những người dắt xe máy.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-4.png', 'p.104 cam xe may'),
('P.105', 'Cấm xe ô tô và xe máy', 'CAM', 'Để báo đường cấm các loại xe cơ giới và xe máy đi qua trừ các xe được ưu tiên theo quy định, đặt biển số P.105 “Cấm xe ô tô và xe máy”.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-5.png', 'p.105 cam xe o to va xe may'),
('P.106a', 'Cấm xe ô tô tải', 'CAM', 'a) Để báo đường cấm các loại xe ô tô tải trừ các xe được ưu tiên theo quy định, đặt biển số P.106a “Cấm xe ô tô tải”. Biển có hiệu lực cấm đối với cả máy kéo và các xe máy chuyên dùng đi vào đoạn đường đặt biển số P.106a. b) Để báo đường cấm các loại xe ô tô tải có khối lượng chuyên chở (theo Giấy chứng nhận kiểm định an toàn kỹ thuật và bảo vệ môi trường phương tiện giao thông cơ giới đường bộ) lớn hơn một giá trị nhất định, đặt biển số P.106b. Biển có hiệu lực cấm các xe ô tô tải có khối lượng chuyên chở (xác định theo Giấy chứng nhận kiểm định an toàn kỹ thuật và bảo vệ môi trường phương tiện giao thông cơ giới đường bộ) lớn hơn giá trị chữ số ghi trong biển (chữ số tấn ghi bằng màu trắng trên hình vẽ xe). Biển có hiệu lực cấm đối với cả máy kéo và các xe máy chuyên dùng đi vào đoạn đường đặt biển. c) Để báo đường cấm các xe chở hàng nguy hiểm, đặt biển số P.106c.', 'QCVN41:2019', 'NEEDS_VERIFICATION', NULL, 'p.106a cam xe o to tai'),
('P.106b', 'Cấm xe ô tô tải', 'CAM', 'a) Để báo đường cấm các loại xe ô tô tải trừ các xe được ưu tiên theo quy định, đặt biển số P.106a “Cấm xe ô tô tải”. Biển có hiệu lực cấm đối với cả máy kéo và các xe máy chuyên dùng đi vào đoạn đường đặt biển số P.106a. b) Để báo đường cấm các loại xe ô tô tải có khối lượng chuyên chở (theo Giấy chứng nhận kiểm định an toàn kỹ thuật và bảo vệ môi trường phương tiện giao thông cơ giới đường bộ) lớn hơn một giá trị nhất định, đặt biển số P.106b. Biển có hiệu lực cấm các xe ô tô tải có khối lượng chuyên chở (xác định theo Giấy chứng nhận kiểm định an toàn kỹ thuật và bảo vệ môi trường phương tiện giao thông cơ giới đường bộ) lớn hơn giá trị chữ số ghi trong biển (chữ số tấn ghi bằng màu trắng trên hình vẽ xe). Biển có hiệu lực cấm đối với cả máy kéo và các xe máy chuyên dùng đi vào đoạn đường đặt biển. c) Để báo đường cấm các xe chở hàng nguy hiểm, đặt biển số P.106c.', 'QCVN41:2019', 'NEEDS_VERIFICATION', NULL, 'p.106b cam xe o to tai'),
('P.106c', 'Cấm các xe chở hàng nguy hiểm', 'CAM', 'a) Để báo đường cấm các loại xe ô tô tải trừ các xe được ưu tiên theo quy định, đặt biển số P.106a “Cấm xe ô tô tải”. Biển có hiệu lực cấm đối với cả máy kéo và các xe máy chuyên dùng đi vào đoạn đường đặt biển số P.106a. b) Để báo đường cấm các loại xe ô tô tải có khối lượng chuyên chở (theo Giấy chứng nhận kiểm định an toàn kỹ thuật và bảo vệ môi trường phương tiện giao thông cơ giới đường bộ) lớn hơn một giá trị nhất định, đặt biển số P.106b. Biển có hiệu lực cấm các xe ô tô tải có khối lượng chuyên chở (xác định theo Giấy chứng nhận kiểm định an toàn kỹ thuật và bảo vệ môi trường phương tiện giao thông cơ giới đường bộ) lớn hơn giá trị chữ số ghi trong biển (chữ số tấn ghi bằng màu trắng trên hình vẽ xe). Biển có hiệu lực cấm đối với cả máy kéo và các xe máy chuyên dùng đi vào đoạn đường đặt biển. c) Để báo đường cấm các xe chở hàng nguy hiểm, đặt biển số P.106c.', 'QCVN41:2019', 'NEEDS_VERIFICATION', NULL, 'p.106c cam cac xe cho hang nguy hiem'),
('P.107', 'Cấm xe ôtô khách và xe ôtô tải', 'CAM', 'Để báo đường cấm xe ô tô chở khách và các loại xe ô tô tải kể cả các loại máy kéo và xe máy chuyên dùng đi qua trừ các xe được ưu tiên theo quy định, đặt biển số P.107 "Cấm xe ô tô khách và xe ô tô tải".', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-7.png', 'p.107 cam xe oto khach va xe oto tai'),
('P.107a', 'Cấm xe ôtô khách', 'CAM', 'a) Để báo đường cấm ô tô chở khách đi qua trừ các xe ưu tiên theo quy định, đặt biển số P.107a “Cấm xe ô tô khách”. Biển này không cấm xe buýt. b) Trường hợp cấm xe khách theo số chỗ ngồi thì sử dụng biển phụ ghi số chỗ ngồi đối với các xe cần cấm hoặc ghi số chỗ ngồi vào biểu tượng xe bằng chữ trắng.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-7.png', 'p.107a cam xe oto khach'),
('P.107b', 'Cấm xe ô tô taxi', 'CAM', 'Để báo đường cấm xe ô tô taxi đi lại, đặt biển số P.107b “Cấm xe ô tô taxi”. Trường hợp cấm xe ô tô taxi theo giờ thì đặt biển phụ ghi giờ cấm.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-7.png', 'p.107b cam xe o to taxi'),
('P.108', 'Cấm xe kéo rơ-moóc', 'CAM', 'Để báo đường cấm các loại xe cơ giới kéo theo rơ-moóc kể cả xe máy, máy kéo, ô tô khách kéo theo rơ-moóc đi lại, trừ loại ôtô sơ-mi rơ-moóc và các xe được ưu tiên (có kéo theo rơ-moóc) theo quy định, đặt biển số P.108 "Cấm xe ô tô, máy kéo kéo rơ-moóc".', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-8.png', 'p.108 cam xe keo ro-mooc'),
('P.108a', 'Cấm xe sơ-mi rơ-moóc', 'CAM', 'Để báo đường cấm các loại xe sơ-mi rơ-moóc và các xe kéo rơ- moóc trừ các xe được ưu tiên (có dạng xe sơ-mi rơ-moóc hoặc có kéo theo rơ-moóc) theo quy định, đặt biển số P.108a "Cấm xe sơ-mi rơ-moóc".', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-8.png', 'p.108a cam xe so-mi ro-mooc'),
('P.109', 'Cấm máy kéo', 'CAM', 'Để báo đường cấm các loại máy kéo, kể cả máy kéo bánh hơi và bánh xích đi qua, đặt biển số P.109 "Cấm máy kéo".', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-9.png', 'p.109 cam may keo'),
('P.110a', 'Cấm xe đạp', 'CAM', 'a) Để báo đường cấm xe đạp đi qua, đặt biển số P.110a "Cấm xe đạp". Biển không có giá trị cấm những người dắt xe đạp. b) Để báo đường cấm xe đạp thồ đi qua, đặt biển số P.110b "Cấm xe đạp thồ". Biển này không cấm người dắt loại xe này.', 'QCVN41:2019', 'NEEDS_VERIFICATION', NULL, 'p.110a cam xe dap'),
('P.110b', 'Cấm xe đạp thồ', 'CAM', 'a) Để báo đường cấm xe đạp đi qua, đặt biển số P.110a "Cấm xe đạp". Biển không có giá trị cấm những người dắt xe đạp. b) Để báo đường cấm xe đạp thồ đi qua, đặt biển số P.110b "Cấm xe đạp thồ". Biển này không cấm người dắt loại xe này.', 'QCVN41:2019', 'NEEDS_VERIFICATION', NULL, 'p.110b cam xe dap tho'),
('P.111a', 'Cấm xe gắn máy', 'CAM', 'a) Để báo đường cấm xe gắn máy đi qua, đặt biển số P.111a "Cấm xe gắn máy". Biển không có giá trị đối với xe đạp. b) Để báo đường cấm xe ba bánh loại có động cơ như xe lam, xe xích lô máy, xe lôi máy, v.v... đặt biển số P.111b hoặc P.111c "Cấm xe ba bánh loại có động cơ". c) Để báo đường cấm xe ba bánh loại không có động cơ như xe xích lô, xe lôi đạp, v.v... đặt biển số P. 111d "Cấm xe ba bánh loại không có động cơ".', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-11.png', 'p.111a cam xe gan may'),
('P.111b', 'Cấm xe ba bánh loại có động cơ', 'CAM', 'a) Để báo đường cấm xe gắn máy đi qua, đặt biển số P.111a "Cấm xe gắn máy". Biển không có giá trị đối với xe đạp. b) Để báo đường cấm xe ba bánh loại có động cơ như xe lam, xe xích lô máy, xe lôi máy, v.v... đặt biển số P.111b hoặc P.111c "Cấm xe ba bánh loại có động cơ". c) Để báo đường cấm xe ba bánh loại không có động cơ như xe xích lô, xe lôi đạp, v.v... đặt biển số P. 111d "Cấm xe ba bánh loại không có động cơ".', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-11.png', 'p.111b cam xe ba banh loai co dong co'),
('P.111c', 'Cấm xe ba bánh loại có động cơ', 'CAM', 'a) Để báo đường cấm xe gắn máy đi qua, đặt biển số P.111a "Cấm xe gắn máy". Biển không có giá trị đối với xe đạp. b) Để báo đường cấm xe ba bánh loại có động cơ như xe lam, xe xích lô máy, xe lôi máy, v.v... đặt biển số P.111b hoặc P.111c "Cấm xe ba bánh loại có động cơ". c) Để báo đường cấm xe ba bánh loại không có động cơ như xe xích lô, xe lôi đạp, v.v... đặt biển số P. 111d "Cấm xe ba bánh loại không có động cơ".', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-11.png', 'p.111c cam xe ba banh loai co dong co'),
('P.111d', 'Cấm xe ba bánh loại không có động cơ', 'CAM', 'a) Để báo đường cấm xe gắn máy đi qua, đặt biển số P.111a "Cấm xe gắn máy". Biển không có giá trị đối với xe đạp. b) Để báo đường cấm xe ba bánh loại có động cơ như xe lam, xe xích lô máy, xe lôi máy, v.v... đặt biển số P.111b hoặc P.111c "Cấm xe ba bánh loại có động cơ". c) Để báo đường cấm xe ba bánh loại không có động cơ như xe xích lô, xe lôi đạp, v.v... đặt biển số P. 111d "Cấm xe ba bánh loại không có động cơ".', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-11.png', 'p.111d cam xe ba banh loai khong co dong co'),
('P.112', 'Cấm người đi bộ', 'CAM', 'Để báo đường cấm người đi bộ qua lại, đặt biển số P.112 "Cấm người đi bộ".', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-12.png', 'p.112 cam nguoi di bo'),
('P.113', 'Cấm xe người kéo, đẩy', 'CAM', 'Để báo đường cấm xe thô sơ, chuyển động do người kéo, đẩy đi qua, đặt biển số P.113 "Cấm xe người kéo, đẩy". Biển không có giá trị cấm những xe nôi của trẻ em và phương tiện chuyên dùng để đi lại của những người khuyết tật.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-13.png', 'p.113 cam xe nguoi keo, day'),
('P.114', 'Cấm xe vật nuôi kéo', 'CAM', 'Để báo đường cấm súc vật vận tải hàng hóa hoặc hành khách dù kéo xe hay chở trên lưng đi qua, đặt biển số P.114 "Cấm xe vật nuôi kéo".', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-14.png', 'p.114 cam xe vat nuoi keo'),
('P.115', 'Hạn chế trọng tải toàn bộ xe', 'CAM', 'Để báo đường cấm các xe (cơ giới và thô sơ) kể cả các xe được ưu tiên theo quy định, có trọng tải toàn bộ xe (trọng tải bản thân xe cộng với khối lượng người, hành lý và hàng hóa xếp trên xe) vượt quá trị số ghi trên biển đi qua, đặt biển số P.115 "Hạn chế trọng tải toàn bộ xe".', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-15.png', 'p.115 han che trong tai toan bo xe'),
('P.116', 'Hạn chế tải trọng trên trục xe', 'CAM', 'Để báo đường cấm các xe (cơ giới và thô sơ) kể cả các xe được ưu tiên theo quy định, có trọng tải toàn bộ xe (cả xe và hàng) phân bổ trên một trục bất kỳ của xe (tải trọng trục xe) vượt quá trị số ghi trên biển đi qua, đặt biển số P.116 "Hạn chế tải trọng trên trục xe".', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-16.png', 'p.116 han che tai trong tren truc xe'),
('P.117', 'Hạn chế chiều cao', 'CAM', 'a) Để báo hạn chế chiều cao của xe, đặt biển số P.117 "Hạn chế chiều cao". b) Biển số P.117 có hiệu lực cấm các xe (cơ giới và thô sơ) có chiều cao vượt quá trị số ghi trên biển đi qua, kể cả các xe được ưu tiên theo quy định (chiều cao tính từ mặt đường, mặt cầu đến điểm cao nhất của xe hoặc hàng). c) Trị số ghi trên biển là khoảng cách từ điểm cao nhất của mặt đường đến điểm thấp nhất của chướng ngại vật vượt trên đường (chiều cao tĩnh không) trừ đi 0,5 m. Cho phép làm tròn số đến 0,1 m theo hướng điều chỉnh tăng (ví dụ: chiều cao thực là 4,65 m; trị số ghi trên biển là: 4,65 - 0,5 = 4,15 làm tròn = 4,2 m). d) Tất cả những vị trí trên đường có chiều cao tĩnh không dưới 4,75 m, đặt biển số P.117 và biển số W.239b. Trường hợp các vị trí có chiều cao tĩnh không từ 4,75 m đến 5,5 m và các vị trí tĩnh không giới hạn trên đường dân sinh (cống, hầm chui dân sinh, ...), chỉ cần đặt biển số W.239b để cảnh báo chiều cao tĩnh không thực tế của các điểm bị hạn chế. Đối với các vị trí có chiều cao tĩnh không trên 5,5 m, không cần đặt biển báo.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-17.png', 'p.117 han che chieu cao'),
('P.118', 'Hạn chế chiều ngang xe', 'CAM', 'a) Để báo hạn chế chiều ngang của xe, đặt biển số P. 118 "Hạn chế chiều ngang xe". b) Biển số P.118 có hiệu lực cấm các xe (cơ giới và thô sơ) kể cả các xe được ưu tiên theo quy định có chiều ngang (kể cả xe và hàng hóa) vượt quá trị số ghi trên biển đi qua. c) Số ghi trên biển là khoảng cách theo chiều ngang ở trạng thái tĩnh nhỏ nhất của vật chướng ngại trên đường trừ đi 0,4 m. d) Những vị trí trên đường có chướng ngại vật mà khoảng cách theo chiều ngang ở trạng thái tĩnh nhỏ hơn 3,2 m, đặt biển số P.118.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-18.png', 'p.118 han che chieu ngang xe'),
('P.119', 'Hạn chế chiều dài xe', 'CAM', 'a) Để báo đường cấm các loại xe (cơ giới và thô sơ) kể cả các xe được ưu tiên theo quy định, có độ dài toàn bộ kể cả xe và hàng lớn hơn trị số ghi trên biển đi qua, đặt biển số P.119 "Hạn chế chiều dài xe". b) Trị số ghi trên biển là chỉ độ dài cho phép lớn nhất tính bằng mét đối với xe đơn chiếc nhằm ngăn ngừa khả năng gây ách tắc giao thông. c) Biển được đặt ở những đoạn đường có bán kính đường cong nằm nhỏ, đèo dốc quanh co hoặc ở những đoạn đường mà xe có chiều dài lớn, gây nguy hiểm.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-19.png', 'p.119 han che chieu dai xe'),
('P.120', 'Hạn chế chiều dài xe cơ giới kéo theo rơ-moóc hoặc sơ-mi rơ- moóc', 'CAM', 'a) Để báo đường cấm các loại xe cơ giới kéo theo moóc kể cả ô tô sơ-mi-rơ-moóc và các loại xe được ưu tiên kéo moóc theo quy định, có độ dài toàn bộ kể cả xe, moóc và hàng lớn hơn trị số ghi trên biển đi qua, đặt biển số P.120 "Hạn chế chiều dài xe cơ giới kéo theo rơ-moóc hoặc sơ-mi rơ moóc". b) Trị số ghi trên biển là chỉ độ dài cho phép lớn nhất tính bằng mét đối với toàn bộ chiều dài đoàn xe kể cả hàng.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-20.png', 'p.120 han che chieu dai xe co gioi keo theo ro-mooc hoac so-mi ro- mooc'),
('P.121', 'Cự ly tối thiểu giữa hai xe', 'CAM', 'a) Để báo xe ô tô phải đi cách nhau một khoảng tối thiểu, đặt biển số P.121 "Cự ly tối thiểu giữa hai xe". b) Số ghi trên biển cho biết khoảng cách tối thiểu tính bằng mét. Biển có hiệu lực cấm các xe ô tô kể cả xe được ưu tiên theo quy định đi cách nhau một cự ly nhỏ hơn trị số ghi trên biển báo. c) Chiều dài có hiệu lực của biển số P.121 được báo bằng biển số S.501 "Phạm vi tác dụng của biển" đặt dưới biển chính (hoặc từ vị trí đặt biển đến vị trí đặt biển số P.135 "Hết tất cả các lệnh cấm" nếu đồng thời có nhiều biển cấm khác hết tác dụng).', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-21.png', 'p.121 cu ly toi thieu giua hai xe'),
('P.123a', 'Cấm rẽ trái', 'CAM', 'a) Để báo cấm rẽ trái hoặc rẽ phải (theo hướng mũi tên chỉ) ở những vị trí đường giao nhau, đặt biển số P.123a "Cấm rẽ trái" hoặc biển số P.123b "Cấm rẽ phải". Biển không có giá trị cấm quay đầu xe. b) Biển có hiệu lực cấm các loại xe (cơ giới và thô sơ) rẽ sang phía trái hoặc phía phải trừ các xe được ưu tiên theo quy định. c) Trước khi đặt biển cấm rẽ, có thể đặt biển chỉ dẫn hướng đi thích hợp.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-23.png', 'p.123a cam re trai'),
('P.123b', 'Cấm rẽ phải', 'CAM', 'a) Để báo cấm rẽ trái hoặc rẽ phải (theo hướng mũi tên chỉ) ở những vị trí đường giao nhau, đặt biển số P.123a "Cấm rẽ trái" hoặc biển số P.123b "Cấm rẽ phải". Biển không có giá trị cấm quay đầu xe. b) Biển có hiệu lực cấm các loại xe (cơ giới và thô sơ) rẽ sang phía trái hoặc phía phải trừ các xe được ưu tiên theo quy định. c) Trước khi đặt biển cấm rẽ, có thể đặt biển chỉ dẫn hướng đi thích hợp.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-23.png', 'p.123b cam re phai'),
('P.124a', 'Cấm quay đầu xe', 'CAM', 'a) Để báo cấm các loại xe quay đầu (theo kiểu chữ U), đặt biển số P.124a "Cấm quay đầu xe". Chiều mũi tên phù hợp với chiều cấm quay đầu xe. b) Để báo cấm xe ô tô quay đầu (theo kiểu chữ U), đặt biển số P.124b "Cấm ô tô quay đầu xe". Chiều mũi tên phù hợp với chiều cấm xe ô tô quay đầu. c) Để báo cấm các loại xe rẽ trái đồng thời cấm quay đầu, đặt biển số P.124c “Cấm rẽ trái và quay đầu xe”. d) Để báo cấm các loại xe rẽ phải đồng thời cấm quay đầu, đặt biển số P.124d “Cấm rẽ phải và quay đầu xe”. e) Để báo cấm xe ô tô rẽ trái và đồng thời cấm quay đầu, đặt biển số P.124e “Cấm ô tô rẽ trái và quay đầu xe”. f) Để báo cấm xe ô tô rẽ phải và đồng thời cấm quay đầu, đặt biển số P.124f “Cấm ô tô rẽ phải và quay đầu xe”. g) Biển số P.124a có hiệu lực cấm các loại xe (cơ giới và thô sơ) và biển số P.124b có hiệu lực cấm xe ô tô và xe máy 3 bánh (side car) quay đầu (theo kiểu chữ U) trừ các xe được ưu tiên theo quy định. Biển không có giá trị cấm rẽ trái để đi sang hướng đường khác. h) Nếu đặt biển "Cấm quay đầu xe" hay biển "Cấm ô tô quay đầu xe" ở một đoạn đường không phải là nơi đường giao nhau thì vị trí bắt đầu cấm, dùng biển số S.503d "Hướng tác dụng của biển" đặt bên dưới biển chính.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-24.png', 'p.124a cam quay dau xe'),
('P.124b', 'Cấm quay đầu xe', 'CAM', 'a) Để báo cấm các loại xe quay đầu (theo kiểu chữ U), đặt biển số P.124a "Cấm quay đầu xe". Chiều mũi tên phù hợp với chiều cấm quay đầu xe. b) Để báo cấm xe ô tô quay đầu (theo kiểu chữ U), đặt biển số P.124b "Cấm ô tô quay đầu xe". Chiều mũi tên phù hợp với chiều cấm xe ô tô quay đầu. c) Để báo cấm các loại xe rẽ trái đồng thời cấm quay đầu, đặt biển số P.124c “Cấm rẽ trái và quay đầu xe”. d) Để báo cấm các loại xe rẽ phải đồng thời cấm quay đầu, đặt biển số P.124d “Cấm rẽ phải và quay đầu xe”. e) Để báo cấm xe ô tô rẽ trái và đồng thời cấm quay đầu, đặt biển số P.124e “Cấm ô tô rẽ trái và quay đầu xe”. f) Để báo cấm xe ô tô rẽ phải và đồng thời cấm quay đầu, đặt biển số P.124f “Cấm ô tô rẽ phải và quay đầu xe”. g) Biển số P.124a có hiệu lực cấm các loại xe (cơ giới và thô sơ) và biển số P.124b có hiệu lực cấm xe ô tô và xe máy 3 bánh (side car) quay đầu (theo kiểu chữ U) trừ các xe được ưu tiên theo quy định. Biển không có giá trị cấm rẽ trái để đi sang hướng đường khác. h) Nếu đặt biển "Cấm quay đầu xe" hay biển "Cấm ô tô quay đầu xe" ở một đoạn đường không phải là nơi đường giao nhau thì vị trí bắt đầu cấm, dùng biển số S.503d "Hướng tác dụng của biển" đặt bên dưới biển chính.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-24.png', 'p.124b cam quay dau xe'),
('P.124c', 'Cấm rẽ trái và quay đầu xe', 'CAM', 'a) Để báo cấm các loại xe quay đầu (theo kiểu chữ U), đặt biển số P.124a "Cấm quay đầu xe". Chiều mũi tên phù hợp với chiều cấm quay đầu xe. b) Để báo cấm xe ô tô quay đầu (theo kiểu chữ U), đặt biển số P.124b "Cấm ô tô quay đầu xe". Chiều mũi tên phù hợp với chiều cấm xe ô tô quay đầu. c) Để báo cấm các loại xe rẽ trái đồng thời cấm quay đầu, đặt biển số P.124c “Cấm rẽ trái và quay đầu xe”. d) Để báo cấm các loại xe rẽ phải đồng thời cấm quay đầu, đặt biển số P.124d “Cấm rẽ phải và quay đầu xe”. e) Để báo cấm xe ô tô rẽ trái và đồng thời cấm quay đầu, đặt biển số P.124e “Cấm ô tô rẽ trái và quay đầu xe”. f) Để báo cấm xe ô tô rẽ phải và đồng thời cấm quay đầu, đặt biển số P.124f “Cấm ô tô rẽ phải và quay đầu xe”. g) Biển số P.124a có hiệu lực cấm các loại xe (cơ giới và thô sơ) và biển số P.124b có hiệu lực cấm xe ô tô và xe máy 3 bánh (side car) quay đầu (theo kiểu chữ U) trừ các xe được ưu tiên theo quy định. Biển không có giá trị cấm rẽ trái để đi sang hướng đường khác. h) Nếu đặt biển "Cấm quay đầu xe" hay biển "Cấm ô tô quay đầu xe" ở một đoạn đường không phải là nơi đường giao nhau thì vị trí bắt đầu cấm, dùng biển số S.503d "Hướng tác dụng của biển" đặt bên dưới biển chính.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-24.png', 'p.124c cam re trai va quay dau xe'),
('P.124d', 'Cấm rẽ phải và quay đầu xe', 'CAM', 'a) Để báo cấm các loại xe quay đầu (theo kiểu chữ U), đặt biển số P.124a "Cấm quay đầu xe". Chiều mũi tên phù hợp với chiều cấm quay đầu xe. b) Để báo cấm xe ô tô quay đầu (theo kiểu chữ U), đặt biển số P.124b "Cấm ô tô quay đầu xe". Chiều mũi tên phù hợp với chiều cấm xe ô tô quay đầu. c) Để báo cấm các loại xe rẽ trái đồng thời cấm quay đầu, đặt biển số P.124c “Cấm rẽ trái và quay đầu xe”. d) Để báo cấm các loại xe rẽ phải đồng thời cấm quay đầu, đặt biển số P.124d “Cấm rẽ phải và quay đầu xe”. e) Để báo cấm xe ô tô rẽ trái và đồng thời cấm quay đầu, đặt biển số P.124e “Cấm ô tô rẽ trái và quay đầu xe”. f) Để báo cấm xe ô tô rẽ phải và đồng thời cấm quay đầu, đặt biển số P.124f “Cấm ô tô rẽ phải và quay đầu xe”. g) Biển số P.124a có hiệu lực cấm các loại xe (cơ giới và thô sơ) và biển số P.124b có hiệu lực cấm xe ô tô và xe máy 3 bánh (side car) quay đầu (theo kiểu chữ U) trừ các xe được ưu tiên theo quy định. Biển không có giá trị cấm rẽ trái để đi sang hướng đường khác. h) Nếu đặt biển "Cấm quay đầu xe" hay biển "Cấm ô tô quay đầu xe" ở một đoạn đường không phải là nơi đường giao nhau thì vị trí bắt đầu cấm, dùng biển số S.503d "Hướng tác dụng của biển" đặt bên dưới biển chính.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-24.png', 'p.124d cam re phai va quay dau xe'),
('P.124e', 'Cấm ô tô rẽ trái và quay đầu xe', 'CAM', 'a) Để báo cấm các loại xe quay đầu (theo kiểu chữ U), đặt biển số P.124a "Cấm quay đầu xe". Chiều mũi tên phù hợp với chiều cấm quay đầu xe. b) Để báo cấm xe ô tô quay đầu (theo kiểu chữ U), đặt biển số P.124b "Cấm ô tô quay đầu xe". Chiều mũi tên phù hợp với chiều cấm xe ô tô quay đầu. c) Để báo cấm các loại xe rẽ trái đồng thời cấm quay đầu, đặt biển số P.124c “Cấm rẽ trái và quay đầu xe”. d) Để báo cấm các loại xe rẽ phải đồng thời cấm quay đầu, đặt biển số P.124d “Cấm rẽ phải và quay đầu xe”. e) Để báo cấm xe ô tô rẽ trái và đồng thời cấm quay đầu, đặt biển số P.124e “Cấm ô tô rẽ trái và quay đầu xe”. f) Để báo cấm xe ô tô rẽ phải và đồng thời cấm quay đầu, đặt biển số P.124f “Cấm ô tô rẽ phải và quay đầu xe”. g) Biển số P.124a có hiệu lực cấm các loại xe (cơ giới và thô sơ) và biển số P.124b có hiệu lực cấm xe ô tô và xe máy 3 bánh (side car) quay đầu (theo kiểu chữ U) trừ các xe được ưu tiên theo quy định. Biển không có giá trị cấm rẽ trái để đi sang hướng đường khác. h) Nếu đặt biển "Cấm quay đầu xe" hay biển "Cấm ô tô quay đầu xe" ở một đoạn đường không phải là nơi đường giao nhau thì vị trí bắt đầu cấm, dùng biển số S.503d "Hướng tác dụng của biển" đặt bên dưới biển chính.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-24.png', 'p.124e cam o to re trai va quay dau xe'),
('P.124f', 'Cấm ô tô rẽ phải và quay đầu xe', 'CAM', 'a) Để báo cấm các loại xe quay đầu (theo kiểu chữ U), đặt biển số P.124a "Cấm quay đầu xe". Chiều mũi tên phù hợp với chiều cấm quay đầu xe. b) Để báo cấm xe ô tô quay đầu (theo kiểu chữ U), đặt biển số P.124b "Cấm ô tô quay đầu xe". Chiều mũi tên phù hợp với chiều cấm xe ô tô quay đầu. c) Để báo cấm các loại xe rẽ trái đồng thời cấm quay đầu, đặt biển số P.124c “Cấm rẽ trái và quay đầu xe”. d) Để báo cấm các loại xe rẽ phải đồng thời cấm quay đầu, đặt biển số P.124d “Cấm rẽ phải và quay đầu xe”. e) Để báo cấm xe ô tô rẽ trái và đồng thời cấm quay đầu, đặt biển số P.124e “Cấm ô tô rẽ trái và quay đầu xe”. f) Để báo cấm xe ô tô rẽ phải và đồng thời cấm quay đầu, đặt biển số P.124f “Cấm ô tô rẽ phải và quay đầu xe”. g) Biển số P.124a có hiệu lực cấm các loại xe (cơ giới và thô sơ) và biển số P.124b có hiệu lực cấm xe ô tô và xe máy 3 bánh (side car) quay đầu (theo kiểu chữ U) trừ các xe được ưu tiên theo quy định. Biển không có giá trị cấm rẽ trái để đi sang hướng đường khác. h) Nếu đặt biển "Cấm quay đầu xe" hay biển "Cấm ô tô quay đầu xe" ở một đoạn đường không phải là nơi đường giao nhau thì vị trí bắt đầu cấm, dùng biển số S.503d "Hướng tác dụng của biển" đặt bên dưới biển chính.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-24.png', 'p.124f cam o to re phai va quay dau xe'),
('P.125', 'Cấm vượt', 'CAM', 'a) Để báo cấm các loại xe cơ giới vượt nhau, đặt biển số P.125 "Cấm vượt". b) Biển có hiệu lực cấm tất cả các loại xe cơ giới vượt nhau (kể cả xe được ưu tiên theo quy định) nhưng được phép vượt xe máy 2 bánh, xe gắn máy. c) Biển hết hiệu lực cấm khi có biển số P.133 "Hết cấm vượt" hoặc đến vị trí đặt biển số P. 135 "Hết tất cả các lệnh cấm" nếu đồng thời có nhiều biển cấm khác hết tác dụng.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-25.png', 'p.125 cam vuot'),
('P.126', 'Cấm xe ô tô tải vượt', 'CAM', 'a) Để báo cấm các loại ô tô tải vượt xe cơ giới khác, đặt biển số P.126 "Cấm xe ô tô tải vượt". b) Biển có hiệu lực cấm các loại ô tô tải có khối lượng chuyên chở (theo Giấy chứng nhận kiểm định an toàn kỹ thuật và bảo vệ môi trường phương tiện giao thông cơ giới đường bộ) lớn hơn 3.500 kg kể cả các xe được ưu tiên theo quy định vượt xe cơ giới khác. Được phép vượt xe máy 2 bánh, xe gắn máy. c) Biển không có giá trị cấm các loại xe cơ giới khác vượt nhau và vượt ô tô tải. d) Biển hết hiệu lực cấm khi có biển số DP.133 "Hết cấm vượt" hoặc đến vị trí đặt biển số DP.135 "Hết tất cả các lệnh cấm" nếu đồng thời có nhiều biển cấm khác hết tác dụng.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-26.png', 'p.126 cam xe o to tai vuot'),
('P.127', 'Tốc độ tối đa cho phép', 'CAM', 'a) Để báo tốc độ tối đa cho phép các xe cơ giới chạy, đặt biển số P.127 "Tốc độ tối đa cho phép"; b) Biển có hiệu lực cấm các loại xe cơ giới chạy với tốc độ tối đa vượt quá trị số ghi trên biển trừ các xe được ưu tiên theo quy định. Người điều khiển phương tiện căn cứ vào điều kiện cụ thể khác như khí hậu thời tiết tình trạng mặt đường, tình hình giao thông, phương tiện, điều kiện sức khỏe để điều khiển phương tiện với tốc độ phù hợp, an toàn và không quá giá trị ghi trên biển; c) Số ghi trên biển tốc độ tối đa cho phép tính bằng km/h và tùy theo tiêu chuẩn kỹ thuật hoặc điều kiện khai thác thực tế của đường mà quy định cho phù hợp. Khi không có các nghiên cứu cụ thể, có thể tham khảo toán đồ trên Hình B.27a để xác định giá trị tốc độ tối đa cho phép cho từng hướng đường; d) Không sử dụng biển số P.127 một cách tràn lan khi không có nghiên cứu cụ thể; e) Trong trường hợp chuyển tiếp từ giá trị tốc độ lớn xuống giá trị tốc độ nhỏ mà sự chênh lệch giữa hai giá trị tốc độ này lớn thì nên đặt biển tốc độ tối đa trung gian. Đoạn chuyển tiếp trung gian được quy định là không nhỏ hơn 250 m cho việc chuyển tiếp từ tốc độ 120 km/h xuống 100 km/h; 200m cho cho việc chuyển tiếp từ tốc độ 100 km/h xuống 80 km/h; 150 m cho việc chuyển tiếp từ tốc độ 80 km/h xuống 60 km/h; 180 m cho việc chuyển tiếp từ tốc độ 90 km/h xuống 60 km/h hoặc từ tốc độ 80 km/h xuống 50 km/h;', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-27b.png', 'p.127 toc do toi da cho phep'),
('P.127a', 'Tốc độ tối đa cho phép về ban đêm', 'CAM', 'a) Khi cần quy định tốc độ tối đa về ban đêm cho các phương tiện, đặt biển số P.127a “Tốc độ tối đa cho phép về ban đêm”. Áp dụng biển số P.127a cho một số trường hợp qua khu đông dân cư vào ban đêm nhằm mục đích nâng cao tốc độ vận hành khi đường ít xe chạy. Biển chỉ có hiệu lực trong thời gian ghi trên biển và trong phạm vi từ vị trí đặt biển đến vị trí biển số R.421 “Hết khu đông dân cư”. Biển được đặt sau vị trí biển số R.420 “Bắt đầu khu đông dân cư”. b) Số ghi trên biển tốc độ tối đa cho phép lớn nhất về ban đêm tính bằng km/h và không lớn hơn 80 km/h. Người tham gia giao thông về ban đêm không được vượt quá giá trị tốc độ ghi trên biển trừ một số trường hợp ưu tiên được quy định. Trong phạm vi hiệu lực của biển số P.127a “Tốc độ tối đa cho phép về ban đêm”, nếu gặp biển số P.127 “Tốc độ tối đa cho phép” thì người lái phải tuân thủ theo giá trị tốc độ tối đa quy định ghi trên biển số P.127.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-27b.png', 'p.127a toc do toi da cho phep ve ban dem'),
('P.127b', 'Biển ghép tốc độ tối đa cho phép trên từng làn đường', 'CAM', 'a) Khi quy định tốc độ tối đa cho phép trên từng làn đường, nếu chỉ sử dụng biển đặt bên đường hoặc trên cột cần vươn hay giá long môn, sử dụng biển số P.127b. Xe chạy trên làn nào phải tuân thủ tốc độ tối đa cho phép trên làn đường đó. b) Biển số P. 127b là biển hình chữ nhật nền màu xanh, trên đó thể hiện tốc độ tối đa trên các làn đường. Biển đặt bên đường hoặc treo trên giá long môn, cột cần vươn.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-27b.png', 'p.127b bien ghep toc do toi da cho phep tren tung lan duong'),
('P.127c', 'Biển ghép tốc độ tối đa cho phép theo phương tiện, trên từng làn đường', 'CAM', 'a) Khi quy định tốc độ tối đa cho phép theo phương tiện trên từng làn đường, sử dụng biển số P.127c. Các loại phương tiện phải đi đúng làn đường và tuân thủ tốc độ tối đa cho phép trên làn đường đó. b) Biển số P.127c là biển hình chữ nhật nền màu xanh, trên đó thể hiện tốc độ tối đa trên các làn đường. Biển đặt bên đường hoặc treo trên cột cần vươn hay giá long môn. Biểu tượng trên biển có thể thay đổi theo điều kiện sử dụng thực tế.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-27b.png', 'p.127c bien ghep toc do toi da cho phep theo phuong tien, tren tung lan duong'),
('DP.127', 'Biển hết tốc độ tối đa cho phép theo biển ghép', 'CAM', 'a) Đến hết đoạn đường tốc độ tối đa cho phép theo biển ghép số P.127b, P.127c, đặt biển số DP.127 “Biển hết tốc độ tối đa cho phép theo biển ghép” tương ứng với các phương án tổ chức giao thông. Trường hợp "Hết tất cả các lệnh cấm" đặt biển số DP.135. b) Biển có giá trị báo cho, người tham gia giao thông biết hiệu lực của biển số P.127(b,c) hết tác dụng. Kể từ biển này, các xe được phép chạy với tốc độ tối đa đã quy định trong Luật Đường bộ và Luật Trật tự, an toàn giao thông đường bộ.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-27d.png', 'dp.127 bien het toc do toi da cho phep theo bien ghep'),
('P.128', 'Cấm sử dụng còi', 'CAM', 'a) Để báo cấm các loại xe sử dụng còi, đặt biển số P.128 "Cấm sử dụng còi". b) Chiều dài có hiệu lực của biển cấm sử dụng còi được báo bằng biển số S.501 "Phạm vi tác dụng của biển" đặt dưới biển chính (hoặc từ vị trí đặt biển đến vị trí đặt biển số DP.135 "Hết tất cả các lệnh cấm" nếu đồng thời có nhiều biển cấm khác hết tác dụng).', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-28.png', 'p.128 cam su dung coi'),
('P.129', 'Kiểm tra', 'CAM', 'Để báo nơi đặt trạm kiểm tra; các loại phương tiện vận tải qua đó phải dừng lại để làm thủ tục kiểm tra, kiểm soát theo quy định, đặt biển số P.129 “Kiểm tra”.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-29.png', 'p.129 kiem tra'),
('P.130', 'Cấm dừng xe và đỗ xe', 'CAM', 'a) Để báo nơi cấm dừng xe và đỗ xe, đặt biển số P.130 "Cấm dừng xe và đỗ xe". Biển có hiệu lực cấm các loại xe cơ giới dừng và đỗ ở phía đường có đặt biển trừ các xe được ưu tiên theo quy định. Đối với các loại xe ô tô buýt chạy theo hành trình quy định được hướng dẫn vị trí dừng thích hợp. b) Hiệu lực cấm của biển bắt đầu từ vị trí đặt biển đến nơi đường giao nhau hoặc đến vị trí quy định đỗ xe, dừng xe (hoặc đến vị trí đặt biển số DP.135 "Hết tất cả các lệnh cấm" nếu đồng thời có nhiều biển cấm khác hết tác dụng). Nếu cần thể hiện đặc biệt thì vị trí bắt đầu cấm phải dùng biển số S.503f và vị trí kết thúc, dùng biển số S.503d "Hướng tác dụng của biển" đặt bên dưới biển chính. c) Trong trường hợp chỉ cấm dừng, đỗ xe vào thời gian nhất định thì dùng biển số S.508 (a, b). d) Trong phạm vi có hiệu lực của biển, nếu có chỗ mở dải phân cách cho phép xe quay đầu thì cần đặt thêm biển số P.130 nhắc lại.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-30.png', 'p.130 cam dung xe va do xe'),
('P.131a', 'Cấm đỗ xe', 'CAM', 'a) Để báo nơi cấm đỗ xe trừ các xe được ưu tiên theo quy định, đặt biển số P.131 (a,b,c) "Cấm đỗ xe". Biển số P.131a có hiệu lực cấm các loại xe cơ giới đỗ ở phía đường có đặt biển. Biển số P.131b có hiệu lực cấm các loại xe cơ giới đỗ ở phía đường có đặt biển vào những ngày lẻ và biển số P.131c vào những ngày chẵn. b) Hiệu lực cấm và thời gian cấm đỗ xe áp dụng theo quy định tại điểm b, c mục B.30 đối với biển số P.130. c) Trong phạm vi có hiệu lực của biển, nếu có chỗ mở dải phân cách cho phép xe quay đầu thì cần đặt thêm biển nhắc lại.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-31.png', 'p.131a cam do xe'),
('P.131b', 'Cấm đỗ xe', 'CAM', 'a) Để báo nơi cấm đỗ xe trừ các xe được ưu tiên theo quy định, đặt biển số P.131 (a,b,c) "Cấm đỗ xe". Biển số P.131a có hiệu lực cấm các loại xe cơ giới đỗ ở phía đường có đặt biển. Biển số P.131b có hiệu lực cấm các loại xe cơ giới đỗ ở phía đường có đặt biển vào những ngày lẻ và biển số P.131c vào những ngày chẵn. b) Hiệu lực cấm và thời gian cấm đỗ xe áp dụng theo quy định tại điểm b, c mục B.30 đối với biển số P.130. c) Trong phạm vi có hiệu lực của biển, nếu có chỗ mở dải phân cách cho phép xe quay đầu thì cần đặt thêm biển nhắc lại.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-31.png', 'p.131b cam do xe'),
('P.131c', 'Cấm đỗ xe', 'CAM', 'a) Để báo nơi cấm đỗ xe trừ các xe được ưu tiên theo quy định, đặt biển số P.131 (a,b,c) "Cấm đỗ xe". Biển số P.131a có hiệu lực cấm các loại xe cơ giới đỗ ở phía đường có đặt biển. Biển số P.131b có hiệu lực cấm các loại xe cơ giới đỗ ở phía đường có đặt biển vào những ngày lẻ và biển số P.131c vào những ngày chẵn. b) Hiệu lực cấm và thời gian cấm đỗ xe áp dụng theo quy định tại điểm b, c mục B.30 đối với biển số P.130. c) Trong phạm vi có hiệu lực của biển, nếu có chỗ mở dải phân cách cho phép xe quay đầu thì cần đặt thêm biển nhắc lại.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-31.png', 'p.131c cam do xe'),
('P.132', 'Nhường đường cho xe cơ giới đi ngược chiều qua đường hẹp', 'CAM', 'a) Để báo các loại xe (cơ giới và thô sơ) kể cả các xe được ưu tiên theo quy định khi thấy biển số P.132 phải nhường đường cho các loại xe cơ giới đang đi theo hướng ngược lại qua các đoạn đường hẹp hoặc cầu hẹp, đặt biển số P.132 "Nhường đường cho xe cơ giới đi ngược chiều qua đường hẹp". b) Biển có hiệu lực đối với các loại xe cơ giới và thô sơ kể cả xe được ưu tiên theo quy định khi đi vào các đoạn đường hẹp có đặt biển số P.132 và trên hướng ngược lại đang có các loại xe cơ giới đi tới thì phải dừng lại ở vị trí thích hợp để nhường đường.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-32.png', 'p.132 nhuong duong cho xe co gioi di nguoc chieu qua duong hep'),
('DP.133', 'Hết cấm vượt', 'CAM', 'Để báo hết đoạn đường cấm vượt, đặt biển số DP.133 "Hết cấm vượt" (hoặc đặt biển số DP.135 "Hết tất cả các lệnh cấm" nếu đồng thời có nhiều biển cấm khác hết tác dụng). Biển có tác dụng báo cho người tham gia giao thông biết hiệu lực của các biển số P.125 và biển số P.126 hết tác dụng. Các xe cơ giới được phép vượt nhau nhưng phải theo quy định về điều kiện cho phép vượt nhau.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-33.png', 'dp.133 het cam vuot'),
('DP.134', 'Hết tốc độ tối đa cho phép', 'CAM', 'a) Đến hết đoạn đường tốc độ tối đa, đặt biển số DP.134 "Hết tốc độ tối đa cho phép" (hoặc đặt biển số DP.135 "Hết tất cả các lệnh cấm" nếu đồng thời có nhiều biển cấm khác hết tác dụng). b) Biển có giá trị báo cho người tham gia giao thông biết hiệu lực của biển số P.127 hết tác dụng. Kể từ biển này, các xe được phép chạy với tốc độ tối đa đã quy định trong Luật Đường bộ và Luật Trật tự, An toàn giao thông đường bộ.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-34.png', 'dp.134 het toc do toi da cho phep'),
('DP.135', 'Hết tất cả các lệnh cấm', 'CAM', 'a) Đến hết đoạn đường mà nhiều biển báo cấm cùng hết hiệu lực, đặt biển số DP.135 ''''Hết tất cả các lệnh cấm". b) Biển có giá trị báo cho người tham gia giao thông biết hiệu lực của biển số P.121 và nhiều biển cấm khác từ biển số P.125 đến biển số P.131 (a,b,c) được đặt trước đó cùng hết tác dụng.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-35.png', 'dp.135 het tat ca cac lenh cam'),
('P.136', 'Cấm đi thẳng', 'CAM', 'Đường ở phía trước cấm tất cả các loại xe (trừ xe ưu tiên theo qui định) đi thẳng, đặt biển số P. 136 "Cấm đi thẳng". Biển được đặt ở vị trí ngay trước nút giao của đường cấm đi thẳng. Nếu có quy định cấm về thời gian và loại xe thì sử dụng biển báo phụ thời gian hoặc hình vẽ loại xe cấm.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-36.png', 'p.136 cam di thang'),
('P.137', 'Cấm rẽ trái, rẽ phải', 'CAM', 'Các ngả đường phía trước cấm tất cả các loại xe (trừ xe ưu tiên theo qui định) rẽ trái hay rẽ phải, đặt biển số P.137 "Cấm rẽ trái, rẽ phải". Biển được đặt ở vị trí ngay trước nút giao của đường cấm rẽ phải, rẽ trái. Nếu có quy định cấm về thời gian hoặc loại xe thì sử dụng biển báo phụ thời gian hoặc hình vẽ loại xe cấm. - Vạch chéo màu đỏ đè lên mũi tên màu đen', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-37.png', 'p.137 cam re trai, re phai'),
('P.138', 'Cấm đi thẳng, rẽ trái', 'CAM', 'Biểu thị đường qua nút giao cấm tất cả các loại xe (trừ xe ưu tiên theo qui định) đi thẳng, rẽ trái, đặt biển số P.138 "Cấm đi thẳng, rẽ trái"; biển đặt ở vị trí ngay trước nút giao. Nếu có quy định cấm về thời gian hoặc loại xe thì sử dụng biển báo phụ thời gian hoặc hình vẽ loại xe cấm.', 'QCVN41:2019', 'NEEDS_VERIFICATION', NULL, 'p.138 cam di thang, re trai'),
('P.139', 'Cấm đi thẳng, rẽ phải', 'CAM', 'Biểu thị đường qua nút giao cấm tất cả các loại xe (trừ xe ưu tiên theo qui định) đi thẳng, rẽ phải, đặt biển số P.139 "Cấm đi thẳng, rẽ phải"; biển đặt ở vị trí ngay trước nút giao. Nếu có quy định cấm về thời gian hoặc loại xe thì sử dụng biển báo phụ thời gian hoặc hình vẽ loại xe cấm.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-39.png', 'p.139 cam di thang, re phai'),
('P.140', 'Cấm xe công nông và các loại xe tương tự', 'CAM', 'Để báo đường cấm xe công nông, đặt biển số 140 “Cấm xe công nông và các loại xe tương tự”.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/B-40.png', 'p.140 cam xe cong nong va cac loai xe tuong tu'),
('W.201a', 'Chỗ ngoặt nguy hiểm', 'NGUY_HIEM', 'a) Để báo trước sắp đến một chỗ ngoặt nguy hiểm, đặt biển số W.201 (a,b): - Biển số W.201a chỗ ngoặt nguy hiểm vòng bên trái; - Biển số W.201b chỗ ngoặt nguy hiểm vòng bên phải. b) Chỗ ngoặt nguy hiểm là vị trí đường cong như sau: - Ở vùng đồng bằng, đường cong có góc chuyển hướng lớn hơn hay bằng 45° hoặc có bán kính nhỏ hơn hay bằng 100 m. - Ở vùng núi, đường cong có góc ở chuyển hướng lớn hơn hay bằng 45° hoặc có bán kính nhỏ hơn hay bằng 40 m. c) Ở những vùng mà việc quan sát của người tham gia giao thông gặp khó khăn như vùng cây rậm rạp, vùng thường có sương mù thì các vị trí đường cong không phân biệt độ lớn góc ở tâm hoặc bán kính đều coi là chỗ ngoặt nguy hiểm. d) Sau đoạn thẳng dài từ 1 km trở lên thì đường cong đầu tiên không phân biệt độ lớn góc ở tâm hoặc bán kính đều coi là chỗ ngoặt nguy hiểm.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-1.png', 'w.201a cho ngoat nguy hiem'),
('W.201b', 'Chỗ ngoặt nguy hiểm', 'NGUY_HIEM', 'a) Để báo trước sắp đến một chỗ ngoặt nguy hiểm, đặt biển số W.201 (a,b): - Biển số W.201a chỗ ngoặt nguy hiểm vòng bên trái; - Biển số W.201b chỗ ngoặt nguy hiểm vòng bên phải. b) Chỗ ngoặt nguy hiểm là vị trí đường cong như sau: - Ở vùng đồng bằng, đường cong có góc chuyển hướng lớn hơn hay bằng 45° hoặc có bán kính nhỏ hơn hay bằng 100 m. - Ở vùng núi, đường cong có góc ở chuyển hướng lớn hơn hay bằng 45° hoặc có bán kính nhỏ hơn hay bằng 40 m. c) Ở những vùng mà việc quan sát của người tham gia giao thông gặp khó khăn như vùng cây rậm rạp, vùng thường có sương mù thì các vị trí đường cong không phân biệt độ lớn góc ở tâm hoặc bán kính đều coi là chỗ ngoặt nguy hiểm. d) Sau đoạn thẳng dài từ 1 km trở lên thì đường cong đầu tiên không phân biệt độ lớn góc ở tâm hoặc bán kính đều coi là chỗ ngoặt nguy hiểm.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-1.png', 'w.201b cho ngoat nguy hiem'),
('W.201c', 'Chỗ ngoặt nguy hiểm có nguy cơ lật xe', 'NGUY_HIEM', 'Để báo trước sắp đến chỗ ngoặt nguy hiểm có khả năng gây lật các xe có trọng tâm cao và trọng tải lớn như xe tải, xe buýt giường nằm, xe chở chất lỏng, v.v... đặt biển số W201(c,d): - Biển số W.201c chỗ ngoặt nguy hiểm có nguy cơ lật xe bên phải khi đường cong vòng sang trái; - Biển số W201d chỗ ngoặt nguy hiểm có nguy cơ lật xe bên trái khi đường cong vòng bên phải.', 'QCVN41:2019', 'NEEDS_VERIFICATION', NULL, 'w.201c cho ngoat nguy hiem co nguy co lat xe'),
('W.201d', 'Chỗ ngoặt nguy hiểm có nguy cơ lật xe', 'NGUY_HIEM', 'Để báo trước sắp đến chỗ ngoặt nguy hiểm có khả năng gây lật các xe có trọng tâm cao và trọng tải lớn như xe tải, xe buýt giường nằm, xe chở chất lỏng, v.v... đặt biển số W201(c,d): - Biển số W.201c chỗ ngoặt nguy hiểm có nguy cơ lật xe bên phải khi đường cong vòng sang trái; - Biển số W201d chỗ ngoặt nguy hiểm có nguy cơ lật xe bên trái khi đường cong vòng bên phải.', 'QCVN41:2019', 'NEEDS_VERIFICATION', NULL, 'w.201d cho ngoat nguy hiem co nguy co lat xe'),
('W.202a', 'Nhiều chỗ ngoặt nguy hiểm liên tiếp', 'NGUY_HIEM', 'a) Để báo trước sắp đến hai chỗ ngoặt ngược chiều nhau liên tiếp, đặt biển số W.202 (a,b): - Biển số W.202a đặt trong trường hợp có từ 2 chỗ ngoặt, ở gần nhau trong đó có ít nhất một chỗ ngoặt nguy hiểm mà chỗ ngoặt đầu tiên hướng vòng bên trái; - Biển số W.202b đặt trong trường hợp như biển số W.202a nhưng hướng vòng bên phải. b) Hai chỗ ngoặt gọi là gần nhau khi đoạn thẳng từ tiếp cuối của đường cong trước đến tiếp đầu của đường cong tiếp sau nhỏ hơn 160 m.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-2.png', 'w.202a nhieu cho ngoat nguy hiem lien tiep'),
('W.202b', 'Nhiều chỗ ngoặt nguy hiểm liên tiếp', 'NGUY_HIEM', 'a) Để báo trước sắp đến hai chỗ ngoặt ngược chiều nhau liên tiếp, đặt biển số W.202 (a,b): - Biển số W.202a đặt trong trường hợp có từ 2 chỗ ngoặt, ở gần nhau trong đó có ít nhất một chỗ ngoặt nguy hiểm mà chỗ ngoặt đầu tiên hướng vòng bên trái; - Biển số W.202b đặt trong trường hợp như biển số W.202a nhưng hướng vòng bên phải. b) Hai chỗ ngoặt gọi là gần nhau khi đoạn thẳng từ tiếp cuối của đường cong trước đến tiếp đầu của đường cong tiếp sau nhỏ hơn 160 m.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-2.png', 'w.202b nhieu cho ngoat nguy hiem lien tiep'),
('W.203a', 'Đường bị thu hẹp', 'NGUY_HIEM', 'a) Để báo trước sắp đến một đoạn đường bị thu hẹp đột ngột, đặt biển số W.203 (a,b,c): - Biển số W.203a đặt trong trường hợp đường bị thu hẹp cả hai bên; - Biển số W.203b hoặc biển số W.203c đặt trong trường hợp đường bị thu hẹp về phía trái hoặc phía phải. b) Đoạn đường bị thu hẹp là đoạn đường mà phần xe chạy bị thu hẹp lại, các làn xe đi ngược chiều nhau gặp khó khăn, nguy hiểm và khả năng thông qua giảm đột ngột so với đoạn đường trước đó. c) Sau khi đặt biển số W.203 (a,b,c) nếu đường bị thu hẹp đến mức không có khả năng thông qua cho hai xe đi ngược chiều thì đặt trước vị trí thu hẹp các biển xác định quyền ưu tiên của chiều đi (biển số P.132 và biển số I.406). d) Ở tất cả những vị trí đường bị hẹp, người tham gia giao thông phải chú ý quan sát giao thông ngược chiều. Xe đi ở chiều đường bị thu hẹp phải nhường đường cho xe đi ngược chiều. e) Nếu trước vị trí bị thu hẹp có đặt biển số P.132 thì phải nhường cho xe chạy ngược chiều; nếu đặt biển số I.406, thì xe được ưu tiên qua đường hẹp trước và xe ngược chiều có trách nhiệm chờ đợi.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-3.png', 'w.203a duong bi thu hep'),
('W.203b', 'Đường bị thu hẹp', 'NGUY_HIEM', 'a) Để báo trước sắp đến một đoạn đường bị thu hẹp đột ngột, đặt biển số W.203 (a,b,c): - Biển số W.203a đặt trong trường hợp đường bị thu hẹp cả hai bên; - Biển số W.203b hoặc biển số W.203c đặt trong trường hợp đường bị thu hẹp về phía trái hoặc phía phải. b) Đoạn đường bị thu hẹp là đoạn đường mà phần xe chạy bị thu hẹp lại, các làn xe đi ngược chiều nhau gặp khó khăn, nguy hiểm và khả năng thông qua giảm đột ngột so với đoạn đường trước đó. c) Sau khi đặt biển số W.203 (a,b,c) nếu đường bị thu hẹp đến mức không có khả năng thông qua cho hai xe đi ngược chiều thì đặt trước vị trí thu hẹp các biển xác định quyền ưu tiên của chiều đi (biển số P.132 và biển số I.406). d) Ở tất cả những vị trí đường bị hẹp, người tham gia giao thông phải chú ý quan sát giao thông ngược chiều. Xe đi ở chiều đường bị thu hẹp phải nhường đường cho xe đi ngược chiều. e) Nếu trước vị trí bị thu hẹp có đặt biển số P.132 thì phải nhường cho xe chạy ngược chiều; nếu đặt biển số I.406, thì xe được ưu tiên qua đường hẹp trước và xe ngược chiều có trách nhiệm chờ đợi.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-3.png', 'w.203b duong bi thu hep'),
('W.203c', 'Đường bị thu hẹp', 'NGUY_HIEM', 'a) Để báo trước sắp đến một đoạn đường bị thu hẹp đột ngột, đặt biển số W.203 (a,b,c): - Biển số W.203a đặt trong trường hợp đường bị thu hẹp cả hai bên; - Biển số W.203b hoặc biển số W.203c đặt trong trường hợp đường bị thu hẹp về phía trái hoặc phía phải. b) Đoạn đường bị thu hẹp là đoạn đường mà phần xe chạy bị thu hẹp lại, các làn xe đi ngược chiều nhau gặp khó khăn, nguy hiểm và khả năng thông qua giảm đột ngột so với đoạn đường trước đó. c) Sau khi đặt biển số W.203 (a,b,c) nếu đường bị thu hẹp đến mức không có khả năng thông qua cho hai xe đi ngược chiều thì đặt trước vị trí thu hẹp các biển xác định quyền ưu tiên của chiều đi (biển số P.132 và biển số I.406). d) Ở tất cả những vị trí đường bị hẹp, người tham gia giao thông phải chú ý quan sát giao thông ngược chiều. Xe đi ở chiều đường bị thu hẹp phải nhường đường cho xe đi ngược chiều. e) Nếu trước vị trí bị thu hẹp có đặt biển số P.132 thì phải nhường cho xe chạy ngược chiều; nếu đặt biển số I.406, thì xe được ưu tiên qua đường hẹp trước và xe ngược chiều có trách nhiệm chờ đợi.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-3.png', 'w.203c duong bi thu hep'),
('W.204', 'Đường hai chiều', 'NGUY_HIEM', 'a) Để báo trước sắp đến đoạn đường do sửa chữa hoặc có trở ngại ở một phía đường mà phải tổ chức đi lại cho phương tiện cả hai chiều trên phía đường còn lại hoặc để báo trước đoạn đường đôi tạm thời hoặc đoạn đường có chiều xe đi và về đi chung thì đặt biển số W.204 "Đường hai chiều". b) Các đoạn đầu và cuối đường có dải phân cách giữa chuyển tiếp sang đường đi chung hai chiều hoặc khi hết đoạn đường một chiều, đặt biển số W.204.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-4.png', 'w.204 duong hai chieu'),
('W.205a', 'Đường giao nhau', 'NGUY_HIEM', 'Để báo trước sắp đến nơi giao nhau cùng mức của các tuyến đường cùng cấp (không có đường nào ưu tiên) trên cùng một mặt bằng, đặt biển số W.205(a,b,c,d,e) "Đường giao nhau". Biển được đặt trước nơi đường giao nhau ở ngoài phạm vi nội thành, nội thị là chủ yếu. Trong nội thành, nội thị có thể châm chước không đặt biển này.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-5.png', 'w.205a duong giao nhau'),
('W.205b', 'Đường giao nhau', 'NGUY_HIEM', 'Để báo trước sắp đến nơi giao nhau cùng mức của các tuyến đường cùng cấp (không có đường nào ưu tiên) trên cùng một mặt bằng, đặt biển số W.205(a,b,c,d,e) "Đường giao nhau". Biển được đặt trước nơi đường giao nhau ở ngoài phạm vi nội thành, nội thị là chủ yếu. Trong nội thành, nội thị có thể châm chước không đặt biển này.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-5.png', 'w.205b duong giao nhau'),
('W.205c', 'Đường giao nhau', 'NGUY_HIEM', 'Để báo trước sắp đến nơi giao nhau cùng mức của các tuyến đường cùng cấp (không có đường nào ưu tiên) trên cùng một mặt bằng, đặt biển số W.205(a,b,c,d,e) "Đường giao nhau". Biển được đặt trước nơi đường giao nhau ở ngoài phạm vi nội thành, nội thị là chủ yếu. Trong nội thành, nội thị có thể châm chước không đặt biển này.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-5.png', 'w.205c duong giao nhau'),
('W.205d', 'Đường giao nhau', 'NGUY_HIEM', 'Để báo trước sắp đến nơi giao nhau cùng mức của các tuyến đường cùng cấp (không có đường nào ưu tiên) trên cùng một mặt bằng, đặt biển số W.205(a,b,c,d,e) "Đường giao nhau". Biển được đặt trước nơi đường giao nhau ở ngoài phạm vi nội thành, nội thị là chủ yếu. Trong nội thành, nội thị có thể châm chước không đặt biển này.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-5.png', 'w.205d duong giao nhau'),
('W.205e', 'Đường giao nhau', 'NGUY_HIEM', 'Để báo trước sắp đến nơi giao nhau cùng mức của các tuyến đường cùng cấp (không có đường nào ưu tiên) trên cùng một mặt bằng, đặt biển số W.205(a,b,c,d,e) "Đường giao nhau". Biển được đặt trước nơi đường giao nhau ở ngoài phạm vi nội thành, nội thị là chủ yếu. Trong nội thành, nội thị có thể châm chước không đặt biển này.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-5.png', 'w.205e duong giao nhau'),
('W.206', 'Giao nhau chạy theo vòng xuyến', 'NGUY_HIEM', 'Để báo trước nơi giao nhau có bố trí đảo an toàn ở giữa nút giao, các loại xe qua nút giao phải đi vòng xuyến quanh đảo an toàn theo chiều mũi tên, đặt biển số W.206 "Giao nhau chạy theo vòng xuyến". Trong nội thành, nội thị có thể không đặt biển này.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-6.png', 'w.206 giao nhau chay theo vong xuyen'),
('W.207a', 'Giao nhau với đường không ưu tiên (đường nhánh)', 'NGUY_HIEM', 'a) Trên đường ưu tiên, để báo trước sắp đến nơi giao nhau với đường không ưu tiên, đặt biển số W.207 (a,b,c,d,e,f,g,h,i,k,l). Tùy theo hình dạng nơi giao nhau và hướng đường ưu tiên hay không ưu tiên để chọn kiểu biển hoặc vẽ hình dạng hình vẽ cho phù hợp với thực tế nút giao. Tại chỗ đường giao với các ngõ, ngách, hẻm hoặc tương tự, tùy theo điều kiện giao thông có thể xem xét sử dụng biển số W.207 khi cần thiết. b) Biển số W.207(a,b,c,d,e,f,g,h,i,k,l) được đặt trước nơi đường giao nhau ở ngoài phạm vi nội thành, nội thị là chính (trong nội thành, nội thị tùy theo điều kiện thực tế để sử dụng biển cho phù hợp). Các xe đi trên đường có đặt biển này được quyền ưu tiên qua nơi giao nhau, chỉ phải nhường đường cho các loại xe được quyền ưu tiên theo quy định. c) Trên tất cả các nhánh đường giao với đoạn đường ưu tiên (đoạn đường nằm giữa biển số I.401 và biển số I.402) ở nơi đường giao nhau, đặt biển số W.208 "Giao nhau với đường ưu tiên". d) Khi đường ưu tiên giao với nhiều đường không ưu tiên liên tiếp với mật độ lớn thì sử dụng biển số W.207d hoặc biển số W.207e kết hợp với sử dụng biển phụ để xác định phạm vi tác dụng của biển (phạm vi đoạn đường giao với nhiều đường không ưu tiên liên tiếp). Trong phạm vi tác dụng của biển số W.207d và W.207e, không cần thiết phải đặt các biển số W.207 khác.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-7.png', 'w.207a giao nhau voi duong khong uu tien (duong nhanh)'),
('W.207b', 'Giao nhau với đường không ưu tiên (đường nhánh)', 'NGUY_HIEM', 'a) Trên đường ưu tiên, để báo trước sắp đến nơi giao nhau với đường không ưu tiên, đặt biển số W.207 (a,b,c,d,e,f,g,h,i,k,l). Tùy theo hình dạng nơi giao nhau và hướng đường ưu tiên hay không ưu tiên để chọn kiểu biển hoặc vẽ hình dạng hình vẽ cho phù hợp với thực tế nút giao. Tại chỗ đường giao với các ngõ, ngách, hẻm hoặc tương tự, tùy theo điều kiện giao thông có thể xem xét sử dụng biển số W.207 khi cần thiết. b) Biển số W.207(a,b,c,d,e,f,g,h,i,k,l) được đặt trước nơi đường giao nhau ở ngoài phạm vi nội thành, nội thị là chính (trong nội thành, nội thị tùy theo điều kiện thực tế để sử dụng biển cho phù hợp). Các xe đi trên đường có đặt biển này được quyền ưu tiên qua nơi giao nhau, chỉ phải nhường đường cho các loại xe được quyền ưu tiên theo quy định. c) Trên tất cả các nhánh đường giao với đoạn đường ưu tiên (đoạn đường nằm giữa biển số I.401 và biển số I.402) ở nơi đường giao nhau, đặt biển số W.208 "Giao nhau với đường ưu tiên". d) Khi đường ưu tiên giao với nhiều đường không ưu tiên liên tiếp với mật độ lớn thì sử dụng biển số W.207d hoặc biển số W.207e kết hợp với sử dụng biển phụ để xác định phạm vi tác dụng của biển (phạm vi đoạn đường giao với nhiều đường không ưu tiên liên tiếp). Trong phạm vi tác dụng của biển số W.207d và W.207e, không cần thiết phải đặt các biển số W.207 khác.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-7.png', 'w.207b giao nhau voi duong khong uu tien (duong nhanh)'),
('W.207c', 'Giao nhau với đường không ưu tiên (đường nhánh)', 'NGUY_HIEM', 'a) Trên đường ưu tiên, để báo trước sắp đến nơi giao nhau với đường không ưu tiên, đặt biển số W.207 (a,b,c,d,e,f,g,h,i,k,l). Tùy theo hình dạng nơi giao nhau và hướng đường ưu tiên hay không ưu tiên để chọn kiểu biển hoặc vẽ hình dạng hình vẽ cho phù hợp với thực tế nút giao. Tại chỗ đường giao với các ngõ, ngách, hẻm hoặc tương tự, tùy theo điều kiện giao thông có thể xem xét sử dụng biển số W.207 khi cần thiết. b) Biển số W.207(a,b,c,d,e,f,g,h,i,k,l) được đặt trước nơi đường giao nhau ở ngoài phạm vi nội thành, nội thị là chính (trong nội thành, nội thị tùy theo điều kiện thực tế để sử dụng biển cho phù hợp). Các xe đi trên đường có đặt biển này được quyền ưu tiên qua nơi giao nhau, chỉ phải nhường đường cho các loại xe được quyền ưu tiên theo quy định. c) Trên tất cả các nhánh đường giao với đoạn đường ưu tiên (đoạn đường nằm giữa biển số I.401 và biển số I.402) ở nơi đường giao nhau, đặt biển số W.208 "Giao nhau với đường ưu tiên". d) Khi đường ưu tiên giao với nhiều đường không ưu tiên liên tiếp với mật độ lớn thì sử dụng biển số W.207d hoặc biển số W.207e kết hợp với sử dụng biển phụ để xác định phạm vi tác dụng của biển (phạm vi đoạn đường giao với nhiều đường không ưu tiên liên tiếp). Trong phạm vi tác dụng của biển số W.207d và W.207e, không cần thiết phải đặt các biển số W.207 khác.', 'QCVN41:2019', 'NEEDS_VERIFICATION', '/signs/raster/C-7.png', 'w.207c giao nhau voi duong khong uu tien (duong nhanh)'),
